using namespace std;
int main() {
    int l, r, ans = 0;
    cin >> l >> r;
    for(int i = l; i <= r; i++) {
        int c = 0, t = i;
        while(t) {
            if(t % 10 == 2)
                c++;
            t /= 10;
        }
        if(c == 3)
            ans++;
    }
    cout << ans;
    return 0;
}

#include <iostream>
